/// Full SRP document with the captured eBay chrome. `river` renders inside
/// `#__app_root__` and `tail` renders just before `</body>` in the same pass.
/// The response owner finalizes the runtime artifacts recorded during render.
pub struct RealSrpDocument<'a, R, T> {
    pub query: &'a str,
    pub total: u64,
    pub river: R,
    pub tail: T,
}

impl<'a, R, T, L: ::proa_core::DataLoader> WebRenderSync<L> for RealSrpDocument<'a, R, T>
where
    R: WebRenderSync<L>,
    T: WebRenderSync<L>,
{
    fn render(self, cx: &mut WebContext<L>) -> Result<(), CoreWriteError> {
        StaticRaw(CHUNK_0).render(cx)?;
        // slot: style_main
        StaticRaw(REAL_STYLE).render(cx)?;
        StaticRaw(CHUNK_1).render(cx)?;
        // slot: title
        text(self.query).render(cx)?;
        StaticRaw(" for sale | eBay").render(cx)?;
        StaticRaw(CHUNK_2).render(cx)?;
        // slot: style_chips
        StaticRaw(CHIPS_STYLE).render(cx)?;
        StaticRaw(CHUNK_3).render(cx)?;
        // slot: query_attr
        escape_attr_value(&mut cx.out, self.query)?;
        StaticRaw(CHUNK_4).render(cx)?;
        // slot: total
        Commas(self.total).render(cx)?;
        StaticRaw(CHUNK_5).render(cx)?;
        // slot: query
        text(self.query).render(cx)?;
        StaticRaw(CHUNK_6).render(cx)?;
        // slot: river
        self.river.render(cx)?;
        StaticRaw(CHUNK_7).render(cx)?;
        // slot: tail
        self.tail.render(cx)?;
        StaticRaw(CHUNK_8).render(cx)?;
        Ok(())
    }
}

/// Render the complete pixel-faithful SRP document in a single pass.
pub fn render_document<R, T>(query: &str, listings: &[Listing], river: R, tail: T) -> String
where
    R: WebRenderSync,
    T: WebRenderSync,
{
    let total = 117_406 + (listings.len() as u64) * 7;
    let mut cx = proa_core::WebContext::new();
    proa_core::WebRenderSync::render(
        RealSrpDocument {
            query,
            total,
            river,
            tail,
        },
        &mut cx,
    )
    .unwrap();
    cx.into_output().into_string()
}
